import{_ as i,l,o as e,c as n,v as o,p as P,x as t,d as p,i as s,S as d}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"工艺窗口 OPC","description":"","frontmatter":{"title":"工艺窗口 OPC","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/pw-opc.md","filePath":"litho/pw-opc.md","lastUpdated":1789023840000}'),E={name:"litho/pw-opc.md"};function h(c,a,C,b,O,A){const r=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="工艺窗口-opc" tabindex="-1">工艺窗口 OPC <a class="header-anchor" href="#工艺窗口-opc" aria-label="Permalink to &quot;工艺窗口 OPC&quot;">​</a></h1><div class="epigraph"><p>名义剂量、名义焦点上的边放对了，窗口角上仍可能先死；修正必须在工艺矩形里同时成立。</p><footer>—— 对照 Cobb 模型基 OPC 与计算光刻中对多工艺点 / PV-band 的公开论述</footer></div><p><a href="/litho/rule-vs-model-opc">上一课</a>把规则表换成可迭代的成像模型，EPE 在校准过的前向里收敛。缺口是：那个前向默认钉在一个工艺点上。剂量、焦点、甚至光源微扰一扫，名义最优边会在角点炸窗。本课钉工艺窗口 OPC（PW-OPC / 多工艺点 OPC）。刻蚀如何再把轮廓挪一截，留给[下一课](/litho/etch-in-opc）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>模型 OPC 的主循环最小化名义条件的边缘放置误差。光刻的合同却是工艺窗口：剂量与焦点在规格矩形内，CD、线端、孔都不越界。名义拟合把碎片推到中心点最优，角点上对比不足或旁瓣升起，PV-band（process variation band）吞掉套刻余量。规则 OPC 更没有「角点」概念，只有中心点标定。</p><p>Cobb 把全芯片迭代做成可能之后，计算光刻的下一步不是更碎的碎片，而是同一套模型在多个工艺点上求一个折中掩模。问题是向量目标：中心点 EPE、焦外 EPE、剂量边 EPE，有时还加光源误差，必须写成一个可加权的代价，而不是修完中心再「看一眼」窗口。</p><h3 id="pv-band-是轮廓包络-不是再报一个-cd" tabindex="-1">PV-band 是轮廓包络，不是再报一个 CD <a class="header-anchor" href="#pv-band-是轮廓包络-不是再报一个-cd" aria-label="Permalink to &quot;PV-band 是轮廓包络，不是再报一个 CD&quot;">​</a></h3><p>在焦点–剂量网格上模拟一圈，轮廓的并集就是 PV-band。带太宽，电学短路或断路；带歪，说明名义 OPC 把边推到了窗口的悬崖。PW-OPC 的目标是把这条带收进设计规则允许的管道，而不是让中心线贴着目标。</p><p><span class="marginnote">只报名义模拟 EPE，等于只报训练集 loss。签核要写清：哪些工艺点进了代价函数，PV-band 是否含胶与（尚未进入的）刻蚀。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在碎片循环里，每次前向不只求名义空中像，而求一组工艺点（典型：焦外 ±、剂量 ±、或其子集）。每个碎片的移动使各点 EPE 的最坏值或加权范数下降，并仍受 MRC 约束。工艺点太多则全芯片算不动；太少则漏掉真正的角。工程是选能代表矩形顶点与已知禁戒节距的点。</p><p>SRAF 对窗口往往比主图形更敏感：助条在名义下印不出，焦外或过量下可能印出。PW-OPC 必须把 SRAF 打印风险当成工艺点约束，而不能只在中心点删助条。</p><h3 id="与-smo-的分工" tabindex="-1">与 SMO 的分工 <a class="header-anchor" href="#与-smo-的分工" aria-label="Permalink to &quot;与 SMO 的分工&quot;">​</a></h3><p><a href="/litho/smo">SMO</a> 先选光源与设计规则，把窗口家族做大；PW-OPC 在给定光源下把每条边收到带内。没有 SMO 的 PW-OPC 会把掩模修成碎形去硬扛坏光源；没有多工艺点的 OPC 会把 SMO 做出的窗在全芯片上局部送掉。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>名义最优与稳健最优不是同一个掩模频谱。中心点爱用高频衬线贴拐角；角点需要更保守的对比，往往少一点锐角、多一点助条余量。投影透镜丢掉的级次在焦外更敏感，所以 PW-OPC 会自然抑制「只在正焦有用」的修正。</p><p>计算量近似按工艺点数倍增，因此要分层：热区多点，规则区少点；或用 PV-band 的包络近似代替全网格。GPU 加速的是同一物理模型的重复前向，不是换一个不稳健的代理。</p><p><span class="marginnote">Cobb 原文解决的是「全芯片模型迭代如何快」。多工艺点是这条路上的目标函数升级，不是另一门学科。不要把 PW-OPC 写成与模型 OPC 并列的商标。</span></p>',18)),(e(),P(d,null,{default:t(()=>[s(r,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20DES%5B%22%E8%AE%BE%E8%AE%A1%E7%9B%AE%E6%A0%87%22%5D%20--%3E%20NOM%5B%22%E5%90%8D%E4%B9%89%E7%82%B9%20OPC%22%5D%0A%20%20DES%20--%3E%20PW%5B%22%E5%A4%9A%E5%B7%A5%E8%89%BA%E7%82%B9%E5%89%8D%E5%90%91%22%5D%0A%20%20NOM%20--%3E%20EPE0%5B%22%E4%B8%AD%E5%BF%83%20EPE%22%5D%0A%20%20PW%20--%3E%20BAND%5B%22PV-band%20%2F%20%E8%A7%92%E7%82%B9%20EPE%22%5D%0A%20%20EPE0%20--%3E%20COST%5B%22%E5%8A%A0%E6%9D%83%E4%BB%A3%E4%BB%B7%22%5D%0A%20%20BAND%20--%3E%20COST%0A%20%20COST%20--%3E%20MOVE%5B%22%E7%A7%BB%E8%BE%B9%20%2F%20%E8%B0%83%20SRAF%22%5D%0A%20%20MOVE%20--%3E%20MRC%5B%22MRC%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课仍在抗蚀剂轮廓（或光学阈值）上谈窗口。刻蚀负荷、胶紧凑模型的内部参数，后两课才进循环。随机缺失孔不是均值 PV-band 能收住的，加再多工艺点也抹不平泊松尾。</p><p>不要发明某 EDA 供应商的内部代价函数名当课程标准。后课默认：说到 OPC 收敛，先问是中心点还是工艺矩形。</p><p><span class="marginnote">「窗口 OPC」不是把工艺窗口画进版图当装饰。它改的是掩模边，评价的是模拟带，签核仍要晶圆 FEM。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>模型 OPC 若只拟合名义点，角点 PV-band 会先死。</li><li>PW-OPC 在多个剂量/焦点上求折中掩模，目标是包络而不是中心线。</li><li>SRAF 打印风险必须当工艺点约束。</li><li>计算量随工艺点涨；热区加密、规则区减点。</li><li>出处：Cobb 模型基 OPC；计算光刻对多工艺点 / PV-band 的公开论述。</li></ul>',6))])}const _=i(E,[["render",h]]);export{m as __pageData,_ as default};
